-- SifoBoarding initial schema proposal. Review before applying to any database.
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,currency char(3) not null default 'ZMW',created_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,created_at timestamptz not null default now(),unique(company_id,name));
create table if not exists public.students(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,student_no text not null,first_name text not null,last_name text not null,guardian_name text,guardian_phone text,status text not null default 'applicant' check(status in('applicant','active','left','suspended')),created_at timestamptz not null default now(),unique(branch_id,student_no));
create table if not exists public.residence_rooms(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,room_no text not null,capacity int not null check(capacity>0),active boolean not null default true,unique(branch_id,room_no));
create table if not exists public.bed_allocations(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,student_id uuid not null references public.students(id),room_id uuid not null references public.residence_rooms(id),bed_label text not null,start_date date not null,end_date date,status text not null default 'active' check(status in('active','ended','cancelled')),created_at timestamptz not null default now(),check(end_date is null or end_date>=start_date));
create table if not exists public.fee_charges(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,student_id uuid not null references public.students(id),description text not null,amount numeric(14,2) not null check(amount>=0),due_date date,status text not null default 'unpaid' check(status in('unpaid','part_paid','paid','waived')),created_at timestamptz not null default now());
create table if not exists public.audit_events(id bigint generated always as identity primary key,company_id uuid not null references public.companies(id) on delete cascade,actor_id uuid,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
